import {lessons,recipes,workflows,commands,sources} from './content.js';
import {analyse,samples,MAX_INPUT} from './analyser.js';
import {scenarios,getScenario} from './model.js';

const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
export const escapeHTML = text => String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
const readPref=(key,fallback)=>{try{return localStorage.getItem(key)??fallback;}catch{return fallback;}};
const writePref=(key,value)=>{try{localStorage.setItem(key,value);}catch{/* Preferences remain usable for this tab. */}};
let completed;try{completed=JSON.parse(readPref('tfu-progress','[]'));if(!Array.isArray(completed))completed=[];}catch{completed=[];}
completed=completed.filter(id=>lessons.some(x=>x.id===id));
let mode=readPref('tfu-mode','guided')==='advanced'?'advanced':'guided';
let theme=readPref('tfu-theme','light')==='dark'?'dark':'light';
let activeFilter='all';
let currentRoute='';
const draft={text:'',phase:'unknown',execution:'unknown',backend:'unknown'};
const main=$('#main');
const toast=message=>{const node=$('#toast');node.textContent=message;node.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('visible'),2500);};
const sourceLink=key=>`<a href="${sources[key]??sources.plan}" target="_blank" rel="noopener noreferrer">Official documentation ↗</a>`;
const command=(text,effect,language='Terminal')=>`<div class="command"><div class="command-head"><span>${e(language)} · ${e(effect)}</span><button type="button" data-copy>Copy</button></div><pre><code>${e(text)}</code></pre></div>`;
const breadcrumb=(parent,label)=>`<div class="breadcrumb"><a href="#home">Home</a> / <a href="#${parent}">${label}</a></div>`;
const pageHead=(eyebrow,title,description)=>`<div class="page-head"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>`;
const lessonCard=l=>`<a class="card" href="#lesson/${l.id}"><span class="card-number">${String(l.number).padStart(2,'0')} / ${e(l.label)}</span><h3>${e(l.title)}</h3><p>${e(l.summary)}</p><span class="text-link">${completed.includes(l.id)?'✓ Revisit lesson':'Start lesson'} <span aria-hidden="true">→</span> <span class="reading-time">· ${l.time}</span></span></a>`;
const problemCard=r=>`<a class="problem-card" href="#recipe/${r.id}"><span class="problem-icon" aria-hidden="true">${e(r.icon)}</span><div><h3>${e(r.title)}</h3><p>${e(r.summary)}</p></div><span class="arrow" aria-hidden="true">↗</span></a>`;
const workflowCard=w=>`<a class="card" href="#workflow/${w.id}"><span class="pill">${e(w.level)}</span><h3>${e(w.title)}</h3><p>${e(w.summary)}</p><span class="text-link">Follow the workflow →</span></a>`;

function home(){
 const common=['state-locked','unexpected-destroy','provider-download','partial-apply','authentication','already-exists'].map(id=>recipes.find(x=>x.id===id));
 return `<section class="hero"><div><div class="eyebrow"><span class="pill">A PRACTICAL TERRAFORM COMPANION</span></div><h1>A clearer plan.<br>A calmer <em>next step.</em></h1><p>Get to grips with Terraform, understand what’s changing, and work through the errors that get in your way.</p><div class="hero-actions"><a class="button primary" href="#learn">Learn Terraform <span aria-hidden="true">→</span></a><a class="button secondary" href="#fix">Fix a problem <span aria-hidden="true">↗</span></a></div><div class="tiny-note">Free to explore. No accounts, cloud access or setup required.</div></div><div class="hero-demo" aria-label="Illustrative Terraform plan"><div class="window-head"><i></i><i></i><i></i><span>understand-the-plan.tf</span><span style="margin-left:auto">SIMULATED EXAMPLE</span></div><div class="demo-body"><div class="demo-caption">SMALL CHANGES. CLEAR CONSEQUENCES.</div><div class="demo-resource"><span class="code-comment"># terraform_data.message will be updated</span><br><span class="code-change">~</span> resource "terraform_data" "message" {<br>&nbsp;&nbsp;<span class="code-change">~</span> input = "Hello" <span class="code-add">→ "Hello again"</span><br>}</div><div class="plan-summary"><span class="code-add">+ 0 to add</span><span class="code-change">~ 1 to change</span><span class="muted">− 0 to destroy</span></div><div class="demo-note"><span aria-hidden="true">ⓘ</span><span>A plan proposes changes. You decide what happens next.</span></div></div></div></section>
 <button class="search-banner" data-open-search><span class="search-icon" aria-hidden="true">⌕</span><span>Search a task, command or error…</span><span class="key">Ctrl K</span></button>
 <section class="section" aria-labelledby="common-heading"><div class="section-heading"><div><h2 id="common-heading">Something not going to plan?</h2><p>Start with what you’re seeing. We’ll help you find your next check.</p></div><a class="text-link" href="#fix">All problems →</a></div><div class="problem-grid">${common.map(problemCard).join('')}</div></section>
 <section class="learning-banner"><div><div class="eyebrow">MAKE IT CLICK</div><h2>Four ideas. One useful mental model.</h2><p>What you want, what Terraform records, what actually exists, and what it proposes. See how they fit together.</p><a class="text-link" href="#lesson/mental-model">Explore the visual model →</a></div><div class="mini-model"><div class="mini-node">01 · Configuration<small>The result you describe</small></div><div class="mini-node">02 · State<small>The object bindings it records</small></div><div class="mini-node">03 · Infrastructure<small>What actually exists now</small></div><div class="mini-node">04 · Plan<small>The changes it proposes</small></div></div></section>
 <section class="section"><div class="section-heading"><div><h2>Build understanding, one step at a time.</h2><p>Short lessons with examples you can actually follow.</p></div><a class="text-link" href="#learn">Learning path →</a></div><div class="cards">${lessons.slice(0,3).map(lessonCard).join('')}</div></section>
 <section class="section"><div class="section-heading"><div><h2>A little guidance for everyday work.</h2><p>Practical workflows, from your first project to a reviewed change.</p></div><a class="text-link" href="#workflows">All workflows →</a></div><div class="cards">${workflows.slice(0,3).map(workflowCard).join('')}</div></section>`;
}
function learn(){return pageHead('LEARN / THE ESSENTIALS','Make Terraform make sense.','Eight short lessons to build a working mental model. Start at the beginning or jump to the idea you need.')+`<div class="callout"><strong>Your learning path</strong><div class="progress-track"><div class="progress-fill" style="width:${completed.length/lessons.length*100}%"></div></div><span class="small">${completed.length} of ${lessons.length} lessons marked complete · Progress is stored only in this browser.</span></div><div class="cards">${lessons.map(lessonCard).join('')}</div>`;}
function lesson(id){
 const l=lessons.find(x=>x.id===id);if(!l)return notFound();
 const next=lessons[l.number];
 return breadcrumb('learn','Learn')+pageHead(`LESSON ${String(l.number).padStart(2,'0')} / ${e(l.time)}`,e(l.title),e(l.summary))+`<div class="article-layout"><article class="article"><h2>The plain-English version</h2><p>${e(l.explanation)}</p><div class="callout"><strong>More precisely</strong><p>${e(l.definition)}</p></div><h2>${e(l.exampleTitle)}</h2>${command(l.example,l.exampleNote,l.id==='desired-state'||l.id==='resources-providers'||l.id==='variables-values'?'HCL example':'Illustrative example')}<h2>A common misconception</h2><p>${e(l.misconception)}</p>${l.simulation?simulator():''}<details class="advanced-only"><summary>A closer look</summary><p>${e(l.advanced)}</p></details><h2>Try this next</h2><p>${e(l.next)}</p>${l.link?`<a class="button small" href="#${l.link}">Open the related guide →</a>`:''}<div class="lesson-next"><button class="button primary" data-complete="${l.id}">${completed.includes(l.id)?'✓ Marked complete':'Mark lesson complete'}</button>${next?`<a class="button" href="#lesson/${next.id}">Next: ${e(next.title)} →</a>`:'<a class="button" href="#workflow/start">Try the local practice project →</a>'}</div></article><aside class="aside"><div class="aside-inner"><h3>In this lesson</h3><p>${e(l.label)} · ${e(l.time)}</p><p>${e(l.version)}</p>${sourceLink(l.source)}<hr class="section-divider"><h3>Learning path</h3>${lessons.map(x=>`<a href="#lesson/${x.id}" ${x.id===l.id?'aria-current="page"':''}>${completed.includes(x.id)?'✓':String(x.number).padStart(2,'0')} · ${e(x.title)}</a>`).join('')}<p>Source reviewed ${l.reviewed}. Examples have not been executed against cloud services.</p><button class="button small" data-share>Copy lesson link</button></div></aside></div>`;
}
function simulator(){return `<section class="simulator" aria-labelledby="sim-heading"><span class="pill">SIMULATION · NO COMMANDS RUN</span><h3 id="sim-heading" style="margin-top:15px">Change one thing. See the proposal.</h3><p>Select a scenario to compare configuration, recorded bindings and current objects.</p><div class="sim-buttons" role="group" aria-label="Simulation scenario">${Object.entries(scenarios).map(([id,s])=>`<button data-scenario="${id}" aria-pressed="${id==='aligned'}">${e(s.label)}</button>`).join('')}</div><div id="sim-output" aria-live="polite">${simulationOutput('aligned')}</div></section>`;}
function simulationOutput(id){const s=getScenario(id);return `<div class="sim-zones"><div class="sim-zone"><b>Configuration</b><code>${e(s.configuration)}</code></div><div class="sim-zone"><b>Recorded binding</b><code>${e(s.recorded)}</code></div><div class="sim-zone"><b>Actual object</b><code>${e(s.actual)}</code></div></div>${command(s.plan,'Simulated proposal','Plan fixture')}<strong class="small">${e(s.summary)}</strong><p style="margin-top:12px">${e(s.reason)}</p><p class="small muted">Fictional provider behaviour for teaching. This is not a prediction for a real resource.</p>`;}
function fix(){return pageHead('FIX / DIAGNOSE BEFORE YOU CHANGE','Let’s find your next check.','Choose a problem below, or paste a sanitised error. Start with the evidence and keep the target environment in view.')+`<section class="analyser" aria-labelledby="analyser-heading"><div class="section-heading"><div><h2 id="analyser-heading">What is Terraform telling you?</h2><p>Local pattern matching · Pasted text stays in tab memory and is never sent by this analyser.</p></div><span class="pill">PRIVATE BY DESIGN</span></div><label class="sr-only" for="error-input">Sanitised Terraform error output</label><textarea id="error-input" placeholder="Paste a sanitised error here…\nFor example: Error: Error acquiring the state lock" spellcheck="false">${e(draft.text)}</textarea><p class="small" id="input-guidance">Remove secrets and personal details. Paste error text only; do not paste state or saved-plan contents. Limit: ${MAX_INPUT.toLocaleString()} characters.</p><details><summary>Add context (optional)</summary><div class="context-grid"><label>Failing phase<select id="context-phase"><option value="unknown">Unknown</option><option value="init">Initialise</option><option value="validate">Validate</option><option value="plan">Plan</option><option value="apply">Apply</option><option value="ci">CI pipeline</option></select></label><label>Execution environment<select id="context-execution"><option value="unknown">Unknown</option><option value="local">Local terminal</option><option value="ci">CI pipeline</option><option value="hcp">HCP Terraform</option></select></label><label>State backend<select id="context-backend"><option value="unknown">Unknown</option><option value="local">Local state</option><option value="remote">Remote backend</option><option value="hcp">HCP Terraform</option></select></label></div><p>Context is kept in this tab and adds checks to the result. It does not override matched evidence.</p></details><div class="analyser-actions"><div><button class="button primary small" id="analyse">Find relevant guidance →</button> <button class="button small" id="clear-input">Clear</button></div><div class="sample-buttons" role="group" aria-label="Try a sample error"><span class="small muted" style="padding:7px">Try a sample:</span><button data-sample="lock">State lock</button><button data-sample="provider">Provider</button><button data-sample="variable">Variable</button><button data-sample="cycle">Cycle</button></div></div><div id="analysis-results" aria-live="polite"></div></section><section aria-labelledby="browse-problems"><div class="section-heading"><div><h2 id="browse-problems">Find a problem by symptom</h2><p>No paste needed. Every guide includes checks, verification and a stop condition.</p></div></div><div class="filter-row" role="group" aria-label="Filter by failing phase">${[['all','All problems'],['setup','Setup'],['init','Initialise'],['validate','Validate'],['plan','Plan'],['apply','Apply'],['ci','CI']].map(([id,title])=>`<button data-filter="${id}" class="${id===activeFilter?'active':''}" aria-pressed="${id===activeFilter}">${title}</button>`).join('')}</div><div class="problem-grid" id="problem-list">${filteredProblems()}</div></section>`;}
function filteredProblems(){return recipes.filter(r=>activeFilter==='all'||r.phase===activeFilter).map(problemCard).join('');}
function recipe(id){
 const r=recipes.find(x=>x.id===id);if(!r)return notFound();
 return breadcrumb('fix','Fix a problem')+pageHead('TROUBLESHOOT / '+e(r.phase.toUpperCase()),e(r.title),e(r.summary))+`<div class="article-layout"><article class="article"><div class="meta"><span class="pill">${e(r.phase)}</span>${r.risk?`<span class="pill">${e(r.risk)}</span>`:''}<span class="reading-time">Source reviewed ${r.reviewed}</span></div><h2>What you are seeing</h2>${command(r.symptom,'Representative symptom; wording varies','Example')}<h2>What it means</h2><p>${e(r.meaning)}</p><h2>Check first</h2><ol>${r.checks.map(x=>`<li>${e(x)}</li>`).join('')}</ol>${r.command?command(r.command,r.effect):''}${r.branch?lockBranch():''}<h2>Choose the matching next step</h2><ol>${r.resolution.map(x=>`<li>${e(x)}</li>`).join('')}</ol><div class="callout success"><strong>How to verify</strong><p>${e(r.verify)}</p></div><div class="callout warning"><strong>When to stop</strong><p>${e(r.stop)}</p></div><details class="advanced-only"><summary>Context and limits</summary><p>${e(r.version)}. This guide is diagnostic guidance, not a complete provider/backend recovery procedure. Follow the exact version’s official documentation and your team’s change process.</p></details><h2>If it still fails</h2><p>Record the failing command, Terraform and provider versions, backend and execution context. Keep the full diagnostic securely, remove sensitive values before sharing, and ask the responsible project or platform owner to review the evidence.</p>${sourceLink(r.source)}<div class="lesson-next"><a class="button" href="#fix">← Browse problems</a><button class="button" data-share>Copy topic link</button></div></article><aside class="aside"><div class="aside-inner"><h3>Before any change</h3><p>Know the working directory, state context and target identity. Check whether another operation is running.</p><h3>Three separate things</h3><p>Restoring configuration, restoring state and recovering infrastructure or data have different effects.</p><a href="#lesson/mental-model">Understand the mental model →</a><a href="#workflow/review">Review a plan →</a><hr class="section-divider">${sourceLink(r.source)}<p>${e(r.version)}</p></div></aside></div>`;
}
function lockBranch(){return `<div class="choice-panel"><label for="lock-owner">What do you know about the lock owner?</label><select id="lock-owner"><option value="unknown">I do not know yet</option><option value="active">Another operation is still active</option><option value="abandoned">The operation is confirmed abandoned</option></select><div id="lock-advice" aria-live="polite"><p>Identify the owner and check the execution queue. Do not remove a lock whose ownership is uncertain.</p></div></div>`;}
function workflow(id){const w=workflows.find(x=>x.id===id);if(!w)return notFound();return breadcrumb('workflows','Workflows')+pageHead(e(w.level),e(w.title),e(w.summary))+`<div class="article-layout"><article class="article"><div class="callout"><strong>Before you start</strong><p>${e(w.intro)}</p></div>${w.steps.map((s,i)=>`<section><h2>${i+1}. ${e(s.title)}</h2><p>${e(s.text)}</p>${s.code?command(s.code,s.effect,s.language??'Terminal'):''}</section>`).join('')}<div class="callout success"><strong>Finished when</strong><p>${e(w.verify)}</p></div><div class="callout warning"><strong>Stop condition</strong><p>${e(w.stop)}</p></div>${sourceLink(w.source)}<div class="lesson-next"><a class="button" href="#workflows">← All workflows</a><button class="button" data-share>Copy workflow link</button></div></article><aside class="aside"><div class="aside-inner"><h3>Work at your pace</h3><p>These steps explain a workflow. Commands run only when you choose to run them in your own environment.</p><a href="#lesson/read-plan">Learn to read a plan →</a><a href="#fix">Something went wrong? →</a><p>Source reviewed ${w.reviewed}. Local example targets Terraform 1.4+. Cloud examples have not been executed.</p></div></aside></div>`;}
function reference(){return pageHead('REFERENCE / KEEP IT HANDY','The command is only half the story.','Look up a command, understand its effect, and follow its official documentation for the version you use.')+`<div class="table-wrap"><table><thead><tr><th>Command</th><th>Purpose</th><th>Effect / limit</th><th>Source</th></tr></thead><tbody>${commands.map(c=>`<tr><td><code>${e(c.name)}</code></td><td>${e(c.purpose)}</td><td>${e(c.effect)}</td><td>${sourceLink(c.source)}</td></tr>`).join('')}</tbody></table></div><div class="callout warning"><strong>No universal undo command</strong><p>State bindings, configuration history and backups of actual data solve different problems. Understand which one you need before attempting recovery.</p></div><section class="section"><h2>Plan symbols, in plain English</h2><div class="cards">${[['+','Create','Proposes a new managed instance.'],['~','Update','Proposes changing an instance in place. Operational impact can still be significant.'],['−','Delete','Proposes removing a managed instance. Check its data and dependencies.'],['−/+ or +/−','Replace','Proposes deleting and creating an instance. Read the actual ordering and reason.']].map(([symbol,title,text])=>`<div class="card"><span class="card-number">${symbol}</span><h3>${title}</h3><p>${text}</p></div>`).join('')}</div></section><section class="section"><h2>Official sources</h2><p class="small">Reviewed 16 October 2026. Check the documentation version selector and your provider’s versioned documentation. Guidance is not a compatibility certification.</p><div class="problem-grid">${Object.entries(sources).map(([key,url])=>`<a class="problem-card" target="_blank" rel="noopener noreferrer" href="${url}"><div><h3>${e(key.charAt(0).toUpperCase()+key.slice(1))}</h3><p>HashiCorp Developer documentation ↗</p></div></a>`).join('')}</div></section>`;}
function about(){return pageHead('ABOUT / A PRACTICAL COMPANION','A clearer route through Terraform.','Terraform Unstuck is an independent visual learning and troubleshooting project inspired by GitUnstuck.')+`<article class="article"><h2>What this early version includes</h2><p>Eight short lessons, 16 troubleshooting recipes, five workflows, a fixture-based plan simulator, global search and 12 error-matching rules. Guided mode keeps explanations focused; Advanced adds optional context.</p><h2>Your input stays in this tab</h2><p>The error analyser uses local pattern matching. It does not send pasted input to a server, put it in share links, save it in browser storage, or use an AI service. Clear removes the draft and diagnosis. Navigating within this guide keeps the draft in memory until the page is reloaded or closed.</p><p>The host still serves website assets and controls access to this private site. External documentation links open the linked service when selected. This application contains no analytics, third-party fonts or remote scripts.</p><h2>What is saved locally</h2><p>Your theme, explanation mode and explicitly marked lesson progress are stored in this browser. They are optional convenience preferences.</p><button id="reset-preferences">Reset saved preferences and progress</button><h2>What this guide cannot know</h2><p>It cannot inspect your accounts, state, configuration or infrastructure. A pattern match is a pointer to guidance, not a confirmed root cause. The simulator uses fictional provider behaviour and does not execute Terraform. Examples have not been tested against live cloud accounts.</p><h2>About the project</h2><p>Built as an early implementation of the Terraform Unstuck plan. Visual conventions draw inspiration from <a href="https://github.com/dazzo31/gitunstuck" target="_blank" rel="noopener noreferrer">GitUnstuck</a>; this implementation uses new source and independent branding.</p><p>Terraform is a HashiCorp product. This project is not affiliated with HashiCorp or IBM.</p></article>`;}
function notFound(){return pageHead('PAGE NOT FOUND','Let’s get you back on track.','This topic link does not match a page in this version.')+'<a class="button primary" href="#home">Go home →</a> <button class="button" data-open-search>Search the guide</button>';}
function render({focus=false}={}){
 const raw=location.hash.slice(1)||'home';
 let route;try{route=decodeURIComponent(raw);}catch{route='not-found';}
 const [type,id]=route.split('/');
 const views={home,learn,fix,workflows:()=>pageHead('WORKFLOWS / ONE TASK AT A TIME','Turn understanding into a next step.','Practical sequences with prerequisites, effects and a clear finish line.')+`<div class="cards">${workflows.map(workflowCard).join('')}</div>`,reference,about};
 main.innerHTML=type==='lesson'?lesson(id):type==='recipe'?recipe(id):type==='workflow'?workflow(id):!id&&views[type]?views[type]():notFound();
 const nav=type==='lesson'?'learn':type==='recipe'?'fix':type==='workflow'?'workflows':type;
 $$('[data-nav]').forEach(a=>{const active=a.dataset.nav===nav;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 const title=type==='lesson'?lessons.find(x=>x.id===id)?.title:type==='recipe'?recipes.find(x=>x.id===id)?.title:type==='workflow'?workflows.find(x=>x.id===id)?.title:({home:'Learn, understand, troubleshoot',learn:'Learn Terraform',fix:'Fix a problem',workflows:'Workflows',reference:'Reference',about:'About & privacy'}[type]);
 document.title=(title??'Topic not found')+' — Terraform Unstuck';
 if(type==='fix')for(const key of ['phase','execution','backend'])$(`#context-${key}`).value=draft[key];
 if(route!==currentRoute){window.scrollTo(0,0);if(focus)main.focus({preventScroll:true});}
 currentRoute=route;
}
function applyPreferences(){document.documentElement.dataset.mode=mode;document.documentElement.dataset.theme=theme;$('#guided-mode').setAttribute('aria-pressed',String(mode==='guided'));$('#advanced-mode').setAttribute('aria-pressed',String(mode==='advanced'));$('#theme-toggle').setAttribute('aria-label',`Switch to ${theme==='light'?'dark':'light'} theme`);}
const searchable=[...lessons.map(x=>({...x,route:'lesson/'+x.id,type:'Lesson'})),...recipes.map(x=>({...x,route:'recipe/'+x.id,type:'Problem'})),...workflows.map(x=>({...x,route:'workflow/'+x.id,type:'Workflow'})),...commands.map(x=>({title:x.name,summary:x.purpose,route:'reference',type:'Command'}))];
function search(query){const terms=query.trim().toLowerCase().split(/\s+/).filter(Boolean);return searchable.filter(x=>terms.every(t=>[x.title,x.summary,...(x.aliases??[])].join(' ').toLowerCase().includes(t))).slice(0,10);}
function showResults(){const q=$('#global-search').value;const results=search(q);$('#search-results').innerHTML=results.length?results.map(x=>`<a class="search-result" href="#${x.route}"><b>${e(x.title)}</b> <span class="pill">${x.type}</span><small>${e(x.summary)}</small></a>`).join(''):'<p class="small" style="padding:20px 0">No matching topics yet. Try a shorter task or browse <a href="#fix">all problems</a>.</p>';}
function openSearch(){const d=$('#search-dialog');if(!d.open)d.showModal();showResults();$('#global-search').focus();}
function runAnalysis(){
 draft.text=$('#error-input').value;
 const result=analyse(draft.text);const node=$('#analysis-results');
 const messages={empty:'Paste an error or try one of the sample buttons.',unknown:'No supported error pattern was recognised. This does not establish that the operation succeeded. Browse by symptom below, or check the complete diagnostic and command.', 'too-large':`This input exceeds ${MAX_INPUT.toLocaleString()} characters. Use a shorter sanitised excerpt around the error.`};
 if(result.status!=='matched'){node.innerHTML=`<div class="callout"><strong>${result.status==='unknown'?'No confident match yet':'Check the input'}</strong><p>${e(messages[result.status])}</p></div>`;return;}
 const context=[];if(draft.execution==='ci')context.push('Check the pipeline run identity and whether another run is active.');if(draft.execution==='hcp')context.push('Check the selected HCP workspace, run queue and run logs.');if(draft.backend==='unknown')context.push('The backend is unknown. Identify the authoritative state before state-related changes.');
 node.innerHTML=`<div class="callout"><strong>${result.matches.length} relevant guide${result.matches.length===1?'':'s'} found</strong><p>These are pattern matches, not confirmed root causes. Read the evidence and check your context.</p></div>${result.matches.map(m=>{const r=recipes.find(x=>x.id===m.id);return `<div class="result-card"><span class="pill">MATCHED EVIDENCE</span><h3 style="margin-top:10px">${e(r.title)}</h3><blockquote>${e(m.evidence)}</blockquote><p>${e(r.meaning)}</p>${draft.phase!=='unknown'&&draft.phase!==r.phase?`<p>Selected phase: ${e(draft.phase)}. This pattern is commonly documented under ${e(r.phase)}; follow the actual failing service and command.</p>`:''}<p><strong>Check first:</strong> ${e(r.checks[0])}</p><a class="button small" href="#recipe/${r.id}">Work through this guide →</a></div>`;}).join('')}${context.length?`<div class="callout"><strong>For your selected context</strong><ul>${context.map(c=>`<li>${e(c)}</li>`).join('')}</ul></div>`:''}`;
}
async function copyText(text){try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(text);toast('Copied to clipboard');}catch{toast('Clipboard unavailable. Select and copy the text manually.');}}
document.addEventListener('click',event=>{
 const el=event.target.closest('button,a');if(!el)return;
 if(el.matches('[data-open-search],#search-toggle'))openSearch();
 if(el.id==='search-close')$('#search-dialog').close();
 if(el.closest('#search-results')&&el.tagName==='A')$('#search-dialog').close();
 if(el.id==='theme-toggle'){theme=theme==='light'?'dark':'light';writePref('tfu-theme',theme);applyPreferences();}
 if(el.id==='guided-mode'||el.id==='advanced-mode'){mode=el.id==='guided-mode'?'guided':'advanced';writePref('tfu-mode',mode);applyPreferences();toast(mode==='advanced'?'Advanced context is now available in the guides.':'Guided explanations selected.');}
 if(el.hasAttribute('data-copy'))copyText($('code',el.closest('.command')).textContent);
 if(el.hasAttribute('data-share')){const url=new URL(location.href);url.search='';copyText(url.href);}
 if(el.dataset.complete){const id=el.dataset.complete;if(!completed.includes(id))completed.push(id);writePref('tfu-progress',JSON.stringify(completed));el.textContent='✓ Marked complete';toast('Lesson marked complete in this browser');}
 if(el.dataset.scenario){$$('[data-scenario]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));$('#sim-output').innerHTML=simulationOutput(el.dataset.scenario);}
 if(el.dataset.sample){draft.text=samples[el.dataset.sample]??'';$('#error-input').value=draft.text;runAnalysis();}
 if(el.id==='analyse')runAnalysis();
 if(el.id==='clear-input'){draft.text='';draft.phase=draft.execution=draft.backend='unknown';$('#error-input').value='';$('#analysis-results').replaceChildren();for(const key of ['phase','execution','backend'])$(`#context-${key}`).value='unknown';$('#error-input').focus();toast('Input, context and diagnosis cleared');}
 if(el.dataset.filter){activeFilter=el.dataset.filter;$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',String(b===el));});$('#problem-list').innerHTML=filteredProblems();}
 if(el.id==='reset-preferences'){for(const key of ['tfu-theme','tfu-mode','tfu-progress'])try{localStorage.removeItem(key);}catch{}theme='light';mode='guided';completed=[];applyPreferences();toast('Saved preferences and lesson progress reset');}
});
document.addEventListener('input',event=>{if(event.target.id==='global-search')showResults();if(event.target.id==='error-input'){draft.text=event.target.value;$('#analysis-results').replaceChildren();}});
document.addEventListener('change',event=>{
 if(event.target.id.startsWith('context-')){draft[event.target.id.slice(8)]=event.target.value;$('#analysis-results').replaceChildren();}
 if(event.target.id==='lock-owner'){const advice={unknown:'Identify the owner and check the execution queue. Do not remove a lock whose ownership is uncertain.',active:'Wait or coordinate with the active run’s owner. Do not force-unlock it or disable locking.',abandoned:'Confirm the exact backend, state context and lock identity with the state owner. Follow that backend’s documented abandoned-lock procedure, then review a fresh normal plan.'};$('#lock-advice').replaceChildren();const p=document.createElement('p');p.textContent=advice[event.target.value];$('#lock-advice').append(p);}
});
$('#global-search').addEventListener('keydown',event=>{if(event.key==='Enter'){const first=$('.search-result');if(first){first.click();}}});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch();}else if(event.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(event.target.tagName)&&!event.target.isContentEditable){event.preventDefault();openSearch();}});
$('#search-dialog').addEventListener('click',event=>{if(event.target===$('#search-dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
window.addEventListener('hashchange',()=>render({focus:true}));
applyPreferences();render();
